from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base BiCG kernel in Exo.
# We explicitly separate the two matrix-vector products:
#   s = A^T r  and  q = A p
# This keeps the object code simple while enabling tiling and parallelization.
@proc
def kernel_bicg(
    m: size,
    n: size,
    A: DATA_TYPE[n, m] @ DRAM,
    s: DATA_TYPE[m] @ DRAM,
    q: DATA_TYPE[n] @ DRAM,
    p: DATA_TYPE[m] @ DRAM,
    r: DATA_TYPE[n] @ DRAM,
):
    # --- Compute s = A^T r ---
    # Initialize s explicitly.
    for j in seq(0, m):
        s[j] = 0.0

    # Row-major traversal of A: for each row i, update all s[j].
    for i in seq(0, n):
        for j in seq(0, m):
            s[j] += r[i] * A[i, j]

    # --- Compute q = A p ---
    # Standard row-major matrix-vector product.
    for k in seq(0, n):
        tmp_q: DATA_TYPE
        tmp_q = 0.0
        for l in seq(0, m):
            tmp_q += A[k, l] * p[l]
        q[k] = tmp_q


# ---------------------------------------------------------------------------
# Scheduling: improve locality for s, and parallelize both matvecs.
# ---------------------------------------------------------------------------

bicg = kernel_bicg

# Tile the (i, j) loop nest that updates s[j].
# We tile only in the column dimension (j). Each tile 'jo' works on a
# contiguous slice of columns, which:
#   - keeps A[i, j] accesses contiguous in memory, and
#   - ensures each tile touches a disjoint slice of s[], making it safe
#     to parallelize across tiles.
J_TILE = 64  # tunable column tile size for cache/locality

# Find the (i, j) loop nest used in the accumulation for s.
i_s = bicg.find_loop("i")               # outer loop over rows in s update
j_s = i_s.body().find_loop("j")        # inner loop over columns

# Split the inner j loop into jo (tile index) and ji (intra-tile index).
# tail="guard" keeps a single loop nest and guards out-of-bounds iterations,
# avoiding a separate remainder loop.
bicg = divide_loop(bicg, j_s, J_TILE, ("jo", "ji"), tail="guard")

# After division we have: for i ... for jo ... for ji ...
# Reorder so that jo is outside i:
#   for jo:
#     for i:
#       for ji:
#         ...
# This makes each jo-iteration responsible for a disjoint slice of s[].
bicg = reorder_loops(bicg, "i jo")

# Parallelize across jo tiles. Each tile writes to a unique range of s[j],
# and only reads A, r, so iterations are independent.
jo_loop = bicg.find_loop("jo")
bicg = parallelize_loop(bicg, jo_loop)

# Parallelize the outer loop of the q = A p matvec: each row k is independent.
k_loop = bicg.find_loop("k")
bicg = parallelize_loop(bicg, k_loop)

# Clean up any guard expressions and index arithmetic introduced above.
bicg = simplify(bicg)

# Expose the scheduled kernel under the original name so that the C driver
# still calls `kernel_bicg`.
kernel_bicg = bicg

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_bicg(/*ctxt=*/NULL, m, n,
	      (DATA_TYPE*)POLYBENCH_ARRAY(A),
	      (DATA_TYPE*)POLYBENCH_ARRAY(s),
	      (DATA_TYPE*)POLYBENCH_ARRAY(q),
	      (DATA_TYPE*)POLYBENCH_ARRAY(p),
	      (DATA_TYPE*)POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

