from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# ---------------------------------------------------------------------------
# Semantic specification of the BiCG kernel
# ---------------------------------------------------------------------------
# This procedure matches the polybench BiCG computation:
#   s[j] = 0              for j in 0..M-1
#   q[i] = sum_j A[i,j]*p[j]          (q = A * p)
#   s[j] = sum_i r[i]*A[i,j]         (s = A^T * r)
#
# We fuse the q and s updates so that each A[i,j] loaded from memory is
# reused for both dot-products, as in the original C kernel.
