    m: size,
    n: size,
    A: DATA_TYPE[n, m] @ DRAM,
    s: DATA_TYPE[m] @ DRAM,
    q: DATA_TYPE[n] @ DRAM,
    p: DATA_TYPE[m] @ DRAM,
    r: DATA_TYPE[n] @ DRAM,
):
    # Initialize s over its m entries
    for j in seq(0, m):
        s[j] = 0.0

    # Scalar temporaries used inside the i-loop. Keeping r[i] and the running
    # value of q[i] in scalars reduces memory traffic and gives the backend
    # compiler a straightforward opportunity to keep them in registers.
    ri: DATA_TYPE
    qi: DATA_TYPE

    # Main BiCG computation
    for i in seq(0, n):
        ri = r[i]
        qi = 0.0
        for j in seq(0, m):
            s[j] += ri * A[i, j]
            qi += A[i, j] * p[j]
        q[i] = qi

# ---------------------------------------------------------------------------
# Scheduling / optimization
# ---------------------------------------------------------------------------

# Tile size for the j-dimension. This can be tuned for the target machine's
# vector width and cache hierarchy.
J_TILE = 32

# Start from the base specification.
kernel_bicg_sched = kernel_bicg_base

